        tours: ["/sri-lanka/colombo/colombo-city-sightseeing-tuk-tuk-hotel-pickup", "/sri-lanka/colombo/colombo-street-food-tuk-tuk-guided-tasting-tour", "/sri-lanka/colombo/colombo-city-highlights-tour-jaffna-style-banana-leaf-lunch"],
