        tours: ["/sri-lanka/sigiriya/private-sigiriya-rock-dambulla-caves-village-day-trip", "/sri-lanka/colombo/dambulla-cave-temples-pidurangala-rock-day-trip-colombo", "/sri-lanka/colombo/private-sigiriya-rock-dambulla-cave-temple-day-trip-lunch"],
